package com.projetok.studio;
import javax.swing.*;
import java.awt.*;
import java.awt.event.*;
import java.nio.file.*;
import java.util.*;

/** Arquivos em worker, confirmacao de descarte e recuperacao explicita de backup. */
final class FileTools {
    final WorldStudio ui;Path file;WorldDocument saved;boolean busy;
    FileTools(WorldStudio ui){this.ui=ui;ui.action("Arquivo","Novo mapa",()->confirm(this::create));ui.action("Arquivo","Abrir",()->confirm(()->open(false)));ui.action("Arquivo","Salvar rascunho",()->save(false,()->{}));ui.action("Arquivo","Salvar rascunho como",()->save(true,()->{}));ui.action("Arquivo","Recuperar backup",()->confirm(()->open(true)));ui.setDefaultCloseOperation(WindowConstants.DO_NOTHING_ON_CLOSE);ui.addWindowListener(new WindowAdapter(){public void windowClosing(WindowEvent e){if(!busy)confirm(ui::dispose);}});saved=ui.document;}
    void confirm(Runnable action){if(busy||ui.liveTools!=null&&!ui.liveTools.confirmDiscard())return;if(ui.document.equals(saved)){action.run();return;}int result=JOptionPane.showConfirmDialog(ui,"Salvar rascunho local antes de continuar? (nao aplica ao jogo)","Rascunho nao salvo",JOptionPane.YES_NO_CANCEL_OPTION);if(result==JOptionPane.YES_OPTION)save(false,action);else if(result==JOptionPane.NO_OPTION)action.run();}
    Path choose(boolean save){JFileChooser chooser=new JFileChooser(file==null?ui.project.resolve("studio-projects").toFile():file.getParent().toFile());chooser.setFileFilter(new javax.swing.filechooser.FileNameExtensionFilter("Mapa World Studio (*.sgmap)","sgmap","bak"));if(file!=null)chooser.setSelectedFile(file.toFile());int choice=save?chooser.showSaveDialog(ui):chooser.showOpenDialog(ui);if(choice!=JFileChooser.APPROVE_OPTION)return null;Path path=chooser.getSelectedFile().toPath().toAbsolutePath();if(save&&!path.toString().endsWith(".sgmap"))path=Path.of(path+".sgmap");return path;}
    void save(boolean as,Runnable after){if(busy)return;Path target=as||file==null?choose(true):file;if(target==null)return;var snapshot=ui.document;busy=true;ui.setEnabled(false);new SwingWorker<Void,Void>(){protected Void doInBackground()throws Exception{DocumentStore.save(target,snapshot);return null;}protected void done(){busy=false;ui.setEnabled(true);try{get();file=target;saved=snapshot;ui.knownMaps.put(snapshot.id(),snapshot);ui.status.setText("Salvo: "+target+" | backup .bak quando houver versao anterior");saveCategories();after.run();}catch(Exception error){ui.error(error);}}}.execute();}
    void open(boolean backup){if(busy)return;Path selected=choose(false);if(selected==null)return;load(backup&&!selected.toString().endsWith(".bak")?Path.of(selected+".bak"):selected,backup);}
    void load(Path target,boolean backup){if(busy)return;busy=true;ui.setEnabled(false);new SwingWorker<WorldDocument,Void>(){final Map<String,WorldDocument> known=new LinkedHashMap<>();final java.util.List<String> warnings=new ArrayList<>();protected WorldDocument doInBackground()throws Exception{var result=DocumentStore.load(target);try(var files=Files.list(target.getParent())){for(Path p:files.filter(f->f.toString().endsWith(".sgmap")).limit(64).toList())try{var d=DocumentStore.load(p);if(known.put(d.id(),d)!=null)warnings.add("ID de mapa duplicado: "+d.id());}catch(Exception error){warnings.add(p.getFileName()+": "+error.getMessage());}}return result;}protected void done(){busy=false;ui.setEnabled(true);try{var d=get();ui.document=ui.history.reset(d);ui.canvas.selected.clear();ui.knownMaps.clear();ui.knownMaps.putAll(known);saved=d;file=backup?null:target;ui.layerTools.refresh();ui.warmImages();ui.canvas.repaint();ui.details.setText(String.join("\n",warnings));ui.status.setText(backup?"Backup aberto; use Salvar como para preservar o arquivo original":"Mapa aberto: "+target);}catch(Exception error){ui.error(error);}}}.execute();}
    void create(){JPanel panel=new JPanel(new GridLayout(0,2));JTextField id=new JTextField("novo_mapa"),name=new JTextField("Novo mapa");JSpinner width=new JSpinner(new SpinnerNumberModel(960,32,8192,32)),height=new JSpinner(new SpinnerNumberModel(640,32,8192,32)),grid=new JSpinner(new SpinnerNumberModel(32,1,256,1));JComboBox<String> region=new JComboBox<>(new String[]{"village","forest","ruins"});for(var row:new Object[][]{{"ID",id},{"Nome",name},{"Largura",width},{"Altura",height},{"Grade",grid},{"Regiao de conteudo",region}}){panel.add(new JLabel((String)row[0]));panel.add((Component)row[1]);}if(JOptionPane.showConfirmDialog(ui,panel,"Novo mapa",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;var d=WorldDocument.empty(id.getText(),(Integer)width.getValue(),(Integer)height.getValue());d=new WorldDocument(1,d.id(),name.getText(),(String)region.getSelectedItem(),d.width(),d.height(),(Integer)grid.getValue(),d.layers(),d.elements(),d.hitboxes(),d.portals(),d.triggers(),d.metadata());ui.document=ui.history.reset(d);saved=null;file=null;ui.canvas.selected.clear();ui.layerTools.refresh();ui.canvas.repaint();}
    void saveCategories(){var catalog=ui.catalog;Path path=ui.project.resolve("studio-projects/catalog.properties");new SwingWorker<Void,Void>(){protected Void doInBackground()throws Exception{Files.createDirectories(path.getParent());Properties p=new Properties();for(var a:catalog.assets())p.setProperty(a.id(),a.category());try(var out=Files.newBufferedWriter(path)){p.store(out,"Categorias locais; PNGs originais preservados");}return null;}protected void done(){try{get();}catch(Exception error){ui.error(error);}}}.execute();}
}
